import{_ as r,C as s,o as p,c as o,j as t,a as m,E as n,a2 as e}from"./chunks/framework.B-bxTAy7.js";const f=JSON.parse('{"title":"模拟电子技术 · 课程主页","description":"模拟电子技术独立课程：二极管与三极管、基本放大电路、频率响应、功率放大、集成运放、反馈、信号运算、波形发生、直流电源，以及传感器与信号调理，10 节正文配交互演示。","frontmatter":{"title":"模拟电子技术 · 课程主页","description":"模拟电子技术独立课程：二极管与三极管、基本放大电路、频率响应、功率放大、集成运放、反馈、信号运算、波形发生、直流电源，以及传感器与信号调理，10 节正文配交互演示。"},"headers":[],"relativePath":"analog/index.md","filePath":"analog/index.md","lastUpdated":1792474335000}'),h={name:"analog/index.md"};function d(c,a,g,u,_,x){const l=s("Meta"),i=s("CourseRoadmap");return p(),o("div",null,[a[0]||(a[0]=t("h1",{id:"模拟电子技术",tabindex:"-1"},[m("模拟电子技术 "),t("a",{class:"header-anchor",href:"#模拟电子技术","aria-label":'Permalink to "模拟电子技术"'},"​")],-1)),n(l,{time:"5 min",level:"指南",note:"从二极管到直流电源，再从电源走到传感器：按『能动手验证』的方式重学一遍"}),a[1]||(a[1]=e('<p>模拟电子技术研究<strong>连续变化</strong>的电压电流：怎么放大、怎么运算、怎么产生波形、怎么把市电变成可用的直流。它和<a href="./../ee/">电工学</a>、<a href="./../digital/">数字电路</a>是三条线：电工学讲电路规律本身，数电讲离散逻辑，模电讲<strong>用半导体器件搭出处理连续信号的系统</strong>。</p><p>本课程按新课从零写，不假设先修。涉及的数学不超过微分和复数（相量），每一章都配可交互演示——把管子特性、工作点、失真、反馈这些抽象名词变成可以拖动验证的东西。</p><h2 id="学完能得到什么" tabindex="-1">学完能得到什么 <a class="header-anchor" href="#学完能得到什么" aria-label="Permalink to &quot;学完能得到什么&quot;">​</a></h2><ul><li>看懂二极管、稳压管、三极管的特性曲线，会判断工作状态、会算静态工作点；</li><li>对共射/共集/共基三种组态，能说出各自的 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>A</mi><mi>u</mi></msub></mrow><annotation encoding="application/x-tex">A_u</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">A</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">u</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>R</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">R_i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>R</mi><mi>o</mi></msub></mrow><annotation encoding="application/x-tex">R_o</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">o</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 数量级与适用场合；</li><li>用波特图判断增益、上限频率与增益带宽积的关系，解释「为什么放大倍数越大越容易丢高频」；</li><li>分清甲类/乙类/甲乙类的效率与交越失真，会估算管耗、选功率管；</li><li>判别反馈的四种组态，用深度负反馈估算闭环增益，并判断会不会自激；</li><li>用运放搭加减、积分、滤波、比较器，最后把整流—滤波—稳压串成一路直流电源；</li><li>把一颗真实传感器（PT100、应变片、热电偶、4–20 mA 变送器）接到 STM32 的 ADC 上：会算电桥输出、选仪表放大器增益、定 RC 抗混叠截止频率、做两点校准与误差预算。</li></ul><h2 id="章节路线" tabindex="-1">章节路线 <a class="header-anchor" href="#章节路线" aria-label="Permalink to &quot;章节路线&quot;">​</a></h2>',5)),n(i,{course:"analog"}),a[2]||(a[2]=e('<h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>顺序</th><th>适合谁</th></tr></thead><tbody><tr><td><strong>速通</strong>（约 4.5 h）</td><td>01 → 02 → 05 → 07 → 09</td><td>只求看懂框图与关键结论</td></tr><tr><td><strong>系统</strong>（约 7.5 h）</td><td>01 → 10 顺序读，重点做 02、06 的演示</td><td>第一次学、要能算</td></tr><tr><td><strong>应用</strong>（约 3 h）</td><td>05 → 07 → 10</td><td>要做传感器采集板、只关心「怎么把信号送进 ADC」</td></tr><tr><td><strong>补强</strong></td><td>失真回 02，波特图回 03，自激回 06</td><td>会做题但概念糊</td></tr></tbody></table><h2 id="关于第-10-章-·-传感器与信号调理" tabindex="-1">关于第 10 章 · 传感器与信号调理 <a class="header-anchor" href="#关于第-10-章-·-传感器与信号调理" aria-label="Permalink to &quot;关于第 10 章 · 传感器与信号调理&quot;">​</a></h2><p>前九章按「器件 → 电路 → 系统」推进，第 10 章是<strong>输出端</strong>：把模电的全部工具用在一条真实的信号链上——传感器输出为什么要放大、电桥的单臂/半桥/全桥为什么差 4 倍、三运放仪表放大器的增益怎么算、RC 抗混叠截止频率怎么定、参考电压与量化误差如何进误差预算，最后落到 STM32 + ADS1115 的完整工程实例。如果只做嵌入式和传感器应用，这一章可以和 05、07 一起直读。</p><h2 id="和其他课程的关系" tabindex="-1">和其他课程的关系 <a class="header-anchor" href="#和其他课程的关系" aria-label="Permalink to &quot;和其他课程的关系&quot;">​</a></h2><ul><li><strong>用电工学打底</strong>：KCL/KVL、相量、戴维南等效是所有分析的基本功，没学过<a href="./../ee/01-basics/model-reference">电工学 01–05 章</a>会明显吃力。</li><li><strong>和数电接口</strong>：模电输出的连续信号要进数电，先得 ADC（见<a href="./../digital/ad-da">数电 08 章</a>）；反方向是 DAC 与 PWM。第 10 章处理的是 ADC <strong>之前</strong>那一段：放大、滤波、校准。</li><li><strong>分立 → 集成的演进</strong>：第 1–4 章用分立器件（看得清机理），<a href="./opamp">第 5 章 · 集成运算放大电路</a>起进入集成运放（省掉偏置设计，专注功能），第 10 章把集成运放的成果直接用到传感器前端。</li></ul><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>器件基础还没打牢：<a href="./../digital/gates">数字电路 · 门电路</a></li><li>直接看传感器这条线：<a href="./10-sensors">10 · 传感器与信号调理</a></li><li>把模拟量送进 MCU：<a href="./../embedded/adc-dma">嵌入式 · ADC 与 DMA</a></li><li>想知道每章的完成度：<a href="./../guide/status">内容状态与成熟度</a></li></ul>',8))])}const v=r(h,[["render",d]]);export{f as __pageData,v as default};
